// store/cart.ts (Zustand sketch)
import { create } from "zustand";

type Item = { id: number; title: string; price: number; qty: number };

type CartState = {
  lines: Item[];
  add: (p: Omit<Item, "qty">) => void;
  remove: (id: number) => void;
  total: () => number;
};

export const useCart = create<CartState>((set, get) => ({
  lines: [],
  add: (p) => set((s) => {
    const existing = s.lines.find((l) => l.id === p.id);
    if (existing) {
      return { lines: s.lines.map((l) => l.id === p.id ? { ...l, qty: l.qty + 1 } : l) };
    }
    return { lines: [...s.lines, { ...p, qty: 1 }] };
  }),
  remove: (id) => set((s) => ({ lines: s.lines.filter((l) => l.id !== id) })),
  total: () => get().lines.reduce((sum, l) => sum + l.price * l.qty, 0),
}));
